import com.example.campbnb.database.Identifiable
import com.example.campbnb.database.WriteEngine
import com.google.android.gms.tasks.OnFailureListener
import com.google.android.gms.tasks.OnSuccessListener
import com.google.android.gms.tasks.Task
import com.google.firebase.firestore.CollectionReference
import com.google.firebase.firestore.DocumentReference
import com.google.firebase.firestore.FirebaseFirestore
import io.mockk.every
import io.mockk.mockk
import io.mockk.slot
import io.mockk.verify
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test

// 🌟 Dummy implementation of Identifiable for the write test
data class TestUserWrite(
    override var id: String, // override to not deal with UUID reinit
    val name: String,
    val age: Int
) : Identifiable()

class WriteEngineTest {

    private lateinit var mockDb: FirebaseFirestore
    private lateinit var mockCollection: CollectionReference
    private lateinit var mockDocRef: DocumentReference
    private lateinit var mockTask: Task<Void>
    private lateinit var writeEngine: WriteEngine<TestUserWrite>

    @Before
    fun setup() {
        mockDb = mockk(relaxed = true)
        mockCollection = mockk(relaxed = true)
        mockDocRef = mockk(relaxed = true)
        mockTask = mockk(relaxed = true)

        // 🌟 Wire up the full hierarchical mock routing chain
        every { mockDb.collection("Users") } returns mockCollection
        every { mockCollection.document(any()) } returns mockDocRef

        // Every database structural mutation returns our tracking task reference
        every { mockDocRef.set(any()) } returns mockTask
        every { mockDocRef.delete() } returns mockTask
        every { mockDocRef.update(any<Map<String, Any?>>()) } returns mockTask

        every { mockTask.addOnSuccessListener(any()) } returns mockTask
        every { mockTask.addOnFailureListener(any()) } returns mockTask

        // Instantiate your exact implementation wrapper
        writeEngine = WriteEngine(mockDb, "Users")
    }

    @Test
    fun test_Save_PassesCorrectDataAndTriggersSuccessCallback() {
        val user = TestUserWrite("user_abc", "Tester", 42)
        val successSlot = slot<OnSuccessListener<Void>>()

        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        // Act
        writeEngine.save(user) { result ->
            testResult = result
        }

        // Simulate a successful remote Firestore transaction completion
        successSlot.captured.onSuccess(null)

        // Assert
        verify(exactly = 1) { mockDb.collection("Users") }
        verify(exactly = 1) { mockCollection.document("user_abc") }
        verify(exactly = 1) { mockDocRef.set(user) }

        assertTrue(testResult!!.isSuccess)
        assertEquals(null, testResult.getOrNull())
    }

    @Test
    fun test_Save_TriggersFailureCallbackOnException() {
        val user = TestUserWrite("user_abc", "Tester", 42)
        val failureSlot = slot<OnFailureListener>()
        val exception = Exception("Firestore security rule violation")

        every { mockTask.addOnFailureListener(capture(failureSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        // Act
        writeEngine.save(user) { result ->
            testResult = result
        }

        // Simulate a write error failure
        failureSlot.captured.onFailure(exception)

        // Assert
        assertTrue(testResult!!.isFailure)
        assertEquals(exception, testResult.exceptionOrNull())
    }

    @Test
    fun test_Delete_CallsCorrectDocumentPathAndTriggersSuccess() {
        val successSlot = slot<OnSuccessListener<Void>>()
        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        // Act
        writeEngine.delete("user_abc") { result ->
            testResult = result
        }
        successSlot.captured.onSuccess(null)

        // Assert
        verify(exactly = 1) { mockCollection.document("user_abc") }
        verify(exactly = 1) { mockDocRef.delete() }
        assertTrue(testResult!!.isSuccess)
    }

    @Test
    fun test_Update_PassesFieldMapAndTriggersSuccess() {
        val updateMap = mapOf("name" to "New Name", "age" to 25)
        val successSlot = slot<OnSuccessListener<Void>>()
        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        // Act
        writeEngine.update("user_abc", updateMap) { result ->
            testResult = result
        }
        successSlot.captured.onSuccess(null)

        // Assert
        verify(exactly = 1) { mockCollection.document("user_abc") }
        verify(exactly = 1) { mockDocRef.update(updateMap) }
        assertTrue(testResult!!.isSuccess)
    }

    // Adversarial additions: blank ids, unknown ids, empty and unusual field maps
    @Test
    fun test_SavingWithBlankId_WritesThatEmptyDocumentPath() {
        val user = TestUserWrite("", "No Name", 1)
        val successSlot = slot<OnSuccessListener<Void>>()
        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        writeEngine.save(user) { result ->
            testResult = result
        }
        successSlot.captured.onSuccess(null)

        assertEquals(null, testResult!!.exceptionOrNull())
        verify(exactly = 1) { mockCollection.document("") }
        verify(exactly = 1) { mockDocRef.set(user) }
    }

    @Test
    fun test_DeleteOfUnknownId_StillReachesThatDocumentPath() {
        val successSlot = slot<OnSuccessListener<Void>>()
        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        writeEngine.delete("was-never-saved") { result ->
            testResult = result
        }
        successSlot.captured.onSuccess(null)

        assertTrue(testResult!!.isSuccess)
        verify(exactly = 1) { mockCollection.document("was-never-saved") }
        verify(exactly = 1) { mockDocRef.delete() }
    }

    @Test
    fun test_UpdateWithEmptyFieldMap_IsStillAnUpdateCall() {
        val emptyFields = emptyMap<String, Any?>()
        val successSlot = slot<OnSuccessListener<Void>>()
        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        writeEngine.update("user_abc", emptyFields) { result ->
            testResult = result
        }
        successSlot.captured.onSuccess(null)

        assertTrue(testResult!!.isSuccess)
        verify(exactly = 1) { mockDocRef.update(emptyMap<String, Any?>()) }
    }

    @Test
    fun test_UpdateWithUnusualFieldNames_ReachesTheDocumentUnchanged() {
        val oddFields = mapOf(
            "camp name" to "two words",
            "meta/name" to 7
        )
        val successSlot = slot<OnSuccessListener<Void>>()
        every { mockTask.addOnSuccessListener(capture(successSlot)) } returns mockTask

        var testResult: Result<Exception?>? = null

        writeEngine.update("user_abc", oddFields) { result ->
            testResult = result
        }
        successSlot.captured.onSuccess(null)

        assertTrue(testResult!!.isSuccess)
        verify(exactly = 1) { mockDocRef.update(oddFields) }
    }
}
